"""Command line entry point: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv."""

from __future__ import annotations

import json
import os
import sys
import tempfile
from typing import Dict, List, Optional, Sequence, Tuple

from .model import summarize

_HEADER = ("customer", "count", "total")


def _read_records(path: str) -> List[object]:
    records: List[object] = []
    with open(path, "r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError as exc:
                raise ValueError(
                    f"{path}: line {line_number}: malformed JSON: {exc}"
                ) from None
    return records


def _quote(value: str) -> str:
    if any(char in value for char in (',', '"', "\n", "\r")):
        return '"' + value.replace('"', '""') + '"'
    return value


def _format_csv(rows: Sequence[Dict[str, object]]) -> str:
    lines = [",".join(_HEADER)]
    for row in rows:
        lines.append(
            ",".join(
                (
                    _quote(str(row["customer"])),
                    str(row["count"]),
                    str(row["total"]),
                )
            )
        )
    return "\n".join(lines) + "\n"


def _write_atomic(path: str, text: str) -> None:
    directory = os.path.dirname(os.path.abspath(path))
    descriptor, temporary = tempfile.mkstemp(
        dir=directory, prefix=".receipt_tmp_", suffix=".csv"
    )
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8", newline="") as handle:
            handle.write(text)
        os.replace(temporary, path)
    except BaseException:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise


def main(argv: Optional[Sequence[str]] = None) -> int:
    arguments = list(sys.argv[1:] if argv is None else argv)
    if len(arguments) != 2:
        print(
            "usage: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv",
            file=sys.stderr,
        )
        return 2
    input_path, output_path = arguments
    try:
        rows = summarize(_read_records(input_path))
        text = _format_csv(rows)
        _write_atomic(output_path, text)
    except Exception as exc:  # noqa: BLE001 - report any failure to stderr
        print(f"error: {type(exc).__name__}: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Receipt validation and summary logic."""

from __future__ import annotations

import re
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Dict, Iterable, List, Mapping, Tuple

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
_PAID = "paid"
_VOID = "void"
_TWO_PLACES = Decimal("0.01")


def _field(record: Mapping, name: str, index: int) -> Any:
    if name not in record:
        raise ValueError(f"record {index}: missing field {name!r}")
    return record[name]


def _validated_customer(record: Mapping, index: int) -> str:
    value = _field(record, "customer", index)
    if not isinstance(value, str):
        raise ValueError(f"record {index}: customer must be a string")
    customer = value.strip()
    if not customer:
        raise ValueError(f"record {index}: customer must be nonempty after strip")
    return customer


def _validated_amount(record: Mapping, index: int) -> Decimal:
    value = _field(record, "amount", index)
    if not isinstance(value, str) or _AMOUNT_RE.fullmatch(value) is None:
        raise ValueError(
            f"record {index}: amount must be an unsigned decimal string"
        )
    return Decimal(value)


def _validated_status(record: Mapping, index: int) -> str:
    value = _field(record, "status", index)
    if value != _PAID and value != _VOID:
        raise ValueError(f"record {index}: status must be 'paid' or 'void'")
    return value


def _format_total(total: Decimal) -> str:
    return str(total.quantize(_TWO_PLACES, rounding=ROUND_HALF_UP))


def summarize(records: Iterable[Mapping]) -> List[Dict[str, Any]]:
    """Summarize receipt dictionaries into sorted per-customer totals.

    Validates every row, combines paid rows by stripped customer name, and
    rounds each customer total once (half up) to two decimal places.
    """
    counts: Dict[str, int] = {}
    totals: Dict[str, Decimal] = {}

    for index, record in enumerate(records):
        if not isinstance(record, Mapping):
            raise ValueError(f"record {index}: receipt must be a mapping")
        customer = _validated_customer(record, index)
        amount = _validated_amount(record, index)
        status = _validated_status(record, index)
        if status == _PAID:
            counts[customer] = counts.get(customer, 0) + 1
            totals[customer] = totals.get(customer, Decimal(0)) + amount

    return [
        {"customer": customer, "count": counts[customer],
         "total": _format_total(totals[customer])}
        for customer in sorted(counts)
    ]

