"""Command-line interface for producing a receipt summary CSV."""

from __future__ import annotations

import argparse
import csv
import json
import os
import sys
import tempfile
from typing import Any

from .model import summarize


def _read_records(path: str) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    with open(path, "r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                raise ValueError(
                    f"invalid JSON on line {line_number}: {exc.msg}"
                ) from None
            if not isinstance(record, dict):
                raise ValueError(f"receipt on line {line_number} must be an object")
            records.append(record)
    return records


def _write_csv_atomic(path: str, rows: list[dict[str, Any]]) -> None:
    directory = os.path.dirname(os.path.abspath(path))
    fd, temp_path = tempfile.mkstemp(
        prefix=".receipt_tools_", suffix=".tmp", dir=directory
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            writer = csv.writer(handle, lineterminator="\n")
            writer.writerow(["customer", "count", "total"])
            for row in rows:
                writer.writerow([row["customer"], row["count"], row["total"]])
        os.replace(temp_path, path)
    except BaseException:
        try:
            os.unlink(temp_path)
        except OSError:
            pass
        raise


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="python -m receipt_tools.cli",
        description="Summarize receipt JSON Lines into a CSV.",
    )
    parser.add_argument("input", help="input JSON Lines file")
    parser.add_argument("output", help="output CSV file")
    args = parser.parse_args(argv)

    try:
        records = _read_records(args.input)
        rows = summarize(records)
        _write_csv_atomic(args.output, rows)
    except Exception as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Validation and summarization of receipt records."""

from __future__ import annotations

import re
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Iterable

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
_CENT = Decimal("0.01")
_VALID_STATUSES = frozenset({"paid", "void"})


def _get_field(record: Any, name: str) -> Any:
    """Fetch a required field, converting missing-field errors to ValueError."""
    try:
        return record[name]
    except (KeyError, IndexError, TypeError):
        raise ValueError(f"missing field: {name}") from None


def summarize(records: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    """Validate receipt records and return per-customer paid summaries.

    Every record is validated, including void records.  Only paid records
    contribute to counts and totals.  Customer names are stripped and equal
    names are combined.  Each customer total is summed with Decimal and
    rounded once to two places using ROUND_HALF_UP.
    """
    counts: dict[str, int] = {}
    totals: dict[str, Decimal] = {}

    for record in records:
        customer = _get_field(record, "customer")
        amount = _get_field(record, "amount")
        status = _get_field(record, "status")

        if not isinstance(customer, str):
            raise ValueError("customer must be a string")
        customer = customer.strip()
        if not customer:
            raise ValueError("customer must be nonempty after stripping")

        if not isinstance(amount, str) or _AMOUNT_RE.fullmatch(amount) is None:
            raise ValueError(
                "amount must be a string matching [0-9]+(?:\\.[0-9]+)?"
            )

        if not isinstance(status, str) or status not in _VALID_STATUSES:
            raise ValueError('status must be exactly "paid" or "void"')

        if status == "paid":
            counts[customer] = counts.get(customer, 0) + 1
            totals[customer] = totals.get(customer, Decimal(0)) + Decimal(amount)

    result: list[dict[str, Any]] = []
    for customer in sorted(totals):
        rounded = totals[customer].quantize(_CENT, rounding=ROUND_HALF_UP)
        result.append(
            {
                "customer": customer,
                "count": counts[customer],
                "total": format(rounded, "f"),
            }
        )
    return result

