import pricing


def quote(items, tier='bronze'):
    lines = []
    amounts = []
    for item in items:
        amount = pricing.price_line(item['unit_price'], item['quantity'], tier)
        amounts.append(amount)
        lines.append({'sku': item['sku'], 'amount': f'{amount:.2f}'})
    total = sum(amounts, 0)
    return {'lines': lines, 'total': f'{total:.2f}'}

"""Single source of truth for line pricing.

Both :mod:`checkout` and :mod:`reporting` call :func:`price_line` dynamically
(``pricing.price_line(...)``) so that replacing this function at runtime
affects every public entry point.
"""

import re
from decimal import Decimal
from fractions import Fraction

# Tier multipliers, matched exactly against the tier name.
TIER_FACTORS = {
    'bronze': Fraction(1, 1),
    'silver': Fraction(9, 10),
    'gold': Fraction(8, 10),
}

# Bulk multiplier applied after the tier multiplier.
BULK_QUANTITY = 10
BULK_FACTOR = Fraction(95, 100)

_MONEY_RE = re.compile(r'[0-9]+(?:\.[0-9]+)?')


def _fail(message):
    raise ValueError(message)


def _parse_unit_price(unit_price):
    """Return the price as an exact Fraction, or raise ValueError."""
    if not isinstance(unit_price, str) or _MONEY_RE.fullmatch(unit_price) is None:
        _fail(f'invalid unit_price: {unit_price!r}')
    return Fraction(unit_price)


def _parse_quantity(quantity):
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
        _fail(f'invalid quantity: {quantity!r}')
    return quantity


def _parse_tier(tier):
    try:
        return TIER_FACTORS[tier]
    except (KeyError, TypeError):
        _fail(f'invalid tier: {tier!r}')


def _to_money(value):
    """Round a nonnegative exact Fraction to 2 decimals, ROUND_HALF_UP."""
    cents = value * 100
    numerator, denominator = cents.numerator, cents.denominator
    rounded = (2 * numerator + denominator) // (2 * denominator)
    return Decimal((0, tuple(int(digit) for digit in str(rounded)), -2))


def price_line(unit_price, quantity, tier='bronze'):
    """Price one line: unit_price * quantity * tier factor * bulk factor.

    ``unit_price`` is an ASCII decimal string, ``quantity`` a nonnegative int
    and ``tier`` one of bronze/silver/gold.  The exact product is rounded once,
    at the end, to 0.01 with ROUND_HALF_UP and returned as a Decimal.
    """
    price = _parse_unit_price(unit_price)
    count = _parse_quantity(quantity)
    factor = _parse_tier(tier)

    value = price * count * factor
    if count >= BULK_QUANTITY:
        value *= BULK_FACTOR
    return _to_money(value)

